fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    // If the input list is empty, return None.
    let mut iter = strings.into_iter();
    let mut best = match iter.next() {
        Some(v) => v,
        None => return None,
    };
    let mut best_len = best.len();

    // Scan the rest of the sequences, updating `best` only if we find a strictly longer one.
    // This way, in case of ties, the earliest maximum‐length sequence remains chosen.
    for s in iter {
        let len = s.len();
        if len > best_len {
            best = s;
            best_len = len;
        }
    }

    Some(best)
}

